```python
from typing import Protocol, runtime_checkable

@runtime_checkable
class Scanner(Protocol):
    def scan(self, amount: int, location: str) -> bool: ...

class Legacy:
    def scan(self): return True

s = Legacy()
print(isinstance(s, Scanner))
try:
    s.scan(10, "BLR")
except TypeError:
    print("TypeError")
```
